/// <summary>
/// This class is used to configure number sequences in BP module.
/// </summary>
/// <remarks>
/// The details of configuring number sequence is in method loadModule().
/// </remarks>
class AVANumberSeqModuleBP extends NumberSeqApplicationModule
{
}

Method.Source:
///  <summary>
///     Configures all the data types that are in use by the module.
///  </summary>
protected void loadModule()
{
    NumberSeqDatatype       dataType = NumberSeqDatatype::construct();

    dataType.parmDatatypeId(extendedTypeNum(KCS_KBVBuildingProjectID));
    dataType.parmReferenceHelp(literalStr("@NDX:NXABuildingProjects"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    //dataType.parmWizardIsChangeDownAllowed(NoYes::Yes);
    //dataType.parmWizardIsChangeUpAllowed(NoYes::Yes);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    dataType.parmSortField(1);
    datatype.parmWizardHighest(999999);        

    // removed for building project ids generated for cross company number sequence
    //datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);

    this.create(dataType);

}

/// <returns>
///    A option of <c>NumberSeqModule</c> representing the BP module
/// </returns>
/// <summary>
///    Returns the NumberSeqModule type for this module
/// </summary>
public NumberSeqModule numberSeqModule()
{
    return NumberSeqModule::AVABuildingProjects;
}

/// <param name="numberSeqModuleNamesMap">
///    A map numberSeqModule names
/// </param>
/// <summary>
///    Appends the current class to the map that links modules to number sequence data type generators.
/// </summary>
[SubscribesTo(classstr(NumberSeqGlobal), delegatestr(NumberSeqGlobal, buildModulesMapDelegate))]
static void buildModulesMapSubsciber(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(AVANumberSeqModuleBP), numberSeqModuleNamesMap);
}

/// <summary>
///    Gets the Numbering reference record in the <c>NumberSequenceReference</c> table.
/// </summary>
/// <returns>
///    A  <c>NumberSequenceReference</c> table; otherwise, an empty record.
/// </returns>
public static NumberSequenceReference numRefKCS_KBVBuildingProjectID()
{
    NumberSeqScope scope;

    // no scope on dataarea
    //scope = NumberSeqScopeFactory::createDataAreaScope(curext());

    return NumberSeqReference::findReference(extendedTypeNum(KCS_KBVBuildingProjectID), scope);
}
